/**
 * ingestion promptfoo output vs committed snapshot parity test.
 *
 * The committed snapshot (`evals/promptfoo/snapshots/ingestion-smoke.json`)
 * was generated by running the ingestion bridge through the promptfoo engine in
 * dry-run (deterministic bundled-fixture derivation). This test re-runs the
 * same bridge + opts and asserts the per-case judgment (caseId + passed +
 * capsuleCount) reproduces the snapshot exactly — no native execution code
 * involved.
 */

import { readFileSync } from 'node:fs';

import { describe, expect, it } from 'vitest';

import { ingestionBridge } from '../ingestion/bridge.js';
import { runSuiteWithPromptfoo } from './runner.js';
import { getSnapshotSuiteConfigs, snapshotFilePath } from './scripts/generate-snapshots.js';
import { suiteSnapshotSchema } from './snapshots/snapshot-schema.js';

describe('ingestion promptfoo output matches committed snapshot', () => {
  it('reproduces the smoke snapshot per-case', async () => {
    const config = getSnapshotSuiteConfigs().find((c) => c.suiteId === 'ingestion');
    expect(config).toBeDefined();
    expect(config!.opts.tier).toBe('smoke');

    const { report, caseCount } = await runSuiteWithPromptfoo(ingestionBridge, config!.opts);
    const entries = config!.extract(report).sort((a, b) => a.caseId.localeCompare(b.caseId));

    const snapshot = suiteSnapshotSchema.parse(
      JSON.parse(readFileSync(snapshotFilePath('ingestion'), 'utf8')),
    );

    expect(snapshot.cases.length).toBeGreaterThan(0);
    expect(caseCount).toBe(snapshot.cases.length);
    expect(entries).toEqual(snapshot.cases);
  });
});
